/* =====================================================
   HORTUS PERENNIS — species data
   =====================================================
   Each entry is the contract the rest of the game renders and plans
   against. drawPlant() uses px-art fields: form, h, cw, sea, stem.
   Planner/rules/export features use inches-truth and site fields:
   type, space, spread, grow, zones, nativeTo, provenance, sun, moist.

   form    one of: bunchgrass | vertgrass | turkeyfoot | cloudgrass |
           feathergrass | moorgrass | fountaingrass | forestgrass |
           oatgrass | cone | globe | spike | umbel (flat/domed corymb —
           yarrow, sedum, joe pye) | drumstick (buttons on wiry stems —
           burnet) | rosette (yucca sword-leaf crown) |
           iris (two-rank sword fan with falls and standards) |
           airywand (gaura's branching butterfly wands) |
           sotol (serrated spoon-leaf rosette with tall panicle) |
           archbell (arching Solomon's seal stems) |
           martagon (recurved lily bells) | pyramid (dense scilla raceme) |
           bractstack (spotted bee balm tiers) | pincushion (scabiosa) |
           agave (symmetric succulent rosette, spine-tipped leaves) |
           ocotillo (spray of tall bare canes, red-tipped in spring) |
           shrub (herbaceous mound) | fern | leafmound (hosta) |
           bulbcup (crocus/tulip/daffodil) | bush (woody shrub, plus
           clipped evergreen forms via look.clip/look.shape/look.hedge) |
           hydrangea (mophead/panicle shrub; look.bloomShape 'mop'|'panicle',
           look.headR sizes the flower heads) | tree (deciduous) | conifer
   type    grass | sedge | forb | bulb | water | shrub | tree - drives the tray
           categories. Bulbs live in their own layer (game.bulbs): they
           share tiles with perennials, bloom in earliest spring while
           the layer above is cut back, and vanish underground by summer
   bloomDay  optional: day-of-season the bloom peaks (bulbs sequence
           through spring: crocus 1, daffodil 3, muscari 4, tulip 6,
           camassia 9); species without it peak by phen (cool 5, mid 8,
           warm 11)
   bloomMonths optional: real-world bloom months as numbers 1-12. This powers
           the Bloom Calendar export and, unless a precise `bloomDay` is
           supplied, the annually continuous in-game bloom window. Missing
           entries fall back to conservative season-to-month estimates so
           every flowering plant still appears in the calendar.
   bulbSeason optional for type:bulb: summer/fall keeps onion bulbs above
           ground outside the default spring-ephemeral window
   grow    woody only: years to mature size (establishment horizon —
           perennials use 10 growing days; a bur oak uses 10 years).
           Woody plants skip the spring cutback; they are structure.
   cw      px-art: woody canopy/twig width for the renderer via
           `woodyVisualCw(P)`. It is not shade reach or footprint size.
   look.coniferHabit optional conifer architecture: spruce (whorled branch
           plates; also used for fir/hemlock), pine (open limbs + needle
           tufts), cedar (horizontal shelves), scale (upright flattened
           sprays), or weeping (pendulous curtains). Shared numeric knobs such
           as tiers, taper, columnar, droop, pads/density and needleLen tune
           species without adding species-specific renderer branches.
           `fullness` expands foliage length/mass without changing real size,
           and `crownMass`/`crownMassW` open or close the crown underwash that
           stops whorls reading as a lattice (pine and true cedar keep a narrow
           core so their rim stays airy; set crownMass:0 for none).
           Weepers additionally use leaderBend, scaffoldDroop, asymmetry and
           numeric leaderDroop to author the bowed leader and cascades. Both
           weeping length knobs are measured against THE GROUND, not against h:
           `scaffoldDroop` is the fraction of its own length that a scaffold arm
           falls, and `weepFall` the fraction of the remaining drop to the
           ground that a hanging strand covers (slightly over 1 at its longest,
           so the skirt breaks the ground line instead of hemming along it).
   h       px-art: mature render height, drawn through plantVisualH(P) — woody
           rescales by the compression factor, herbaceous scales by HERB_SCALE
           (~1.75, so drifts read as masses), bulbs pass through. Every
           herbaceous form derives its whole geometry from the drawn height, so
           that one factor scales the plant's width too. It is not a real-world
           height, footprint, shade, order, or spacing unit.
   heightIn inches-truth: real mature height. REQUIRED for type:'tree' and
           type:'shrub'; cards/library show heightIn first. A shrub's px-art h
           often sits near 1:1 with inches, but keeping the two explicit stops
           compact cultivars from inheriting the base plant's mature height.
           Herbaceous plants may omit it and fall back to h.
   space   inches-truth: on-center planting distance (what you'd order/space by)
   spread  inches-truth: mature clump/crown width. For woody plants this is
           the only source for `woodyRadiusTiles(P)`, which drives shrub
           reservations, tree shade/canopy rings, plan circles, and overlays.
   zones   [min,max] USDA hardiness range
   nativeTo explicit broad native ranges. North America and Europe are the
           first selectable garden ranges; Asia, Africa, Central America,
           South America, and Australasia preserve worldwide origin facts.
   provenance species | selection | hybrid. Named cultivars resolve to
           selection unless an explicit hybrid or exact-species override says
           otherwise. Native eligibility is computed from both fields.
   sun     full | part — primary light preference
   moist   dry | medium | moist — primary soil preference
   phen    cool | mid | warm — when it wakes in spring and peaks:
           cool-season plants (sedges, Calamagrostis, the spring
           bloomers) emerge first; warm-season prairie grasses and
           late risers like butterfly weed wait for real heat
   stem    optional stem color override (salvia's near-black stems)
   cv      optional named cultivars: { key:{ name:"'Cultivar'", note,
           ...overrides } }. Overrides merge over the straight species —
           h, stem, look keys, and per-season sea keys. Cultivar names are facts
           (nominative use; names aren't copyrightable) — plant patents
           restrict propagation, not depiction. Avoid trademarked TRADE
           names as branding; the cultivar name in quotes is safe.
   group   optional family handle ('coneflower'): species sharing it
           collapse into one tray button, and the chip row picks the
           species (each stays a full entry — own latin, zones)
   chip    short label for this species' chip inside its group
   look    optional rendering tweaks for plant forms. Grasses use it for
           leaf count, fan, mound/cloud/plume density; cone forms use
           rays (count), rayLen, rayW, droop (how hard the rays fall),
           stems, leaves, leafW, leafLen — leafy purpurea vs wispy
           pallida vs hard-reflexed atrorubens; `rayShape:'poppy'` gives
           four broad petals their dark basal marks
           Spike forms may select `spikeStyle:'liatris'|'bell'|'penstemon'|
           'culvers'|'prairieClover'|'goldenrodPanicle'|'poker'|'delphinium'`;
           pincushion forms may select
           `pincushionStyle:'astrantia'`; globe forms may select
           `globeStyle:'seaHolly'`.
           Tree forms may select `fruitShape:'round'|'pear'|'fig'|'oval'|
           'pod'|'nut'|'husk'|'bur'|'pomegranate'`; `fruitCluster` packs the
           authored `seedN` total into bounded bunches without adding glyphs.
           A deliberate `seedN:0` suppresses fruit on male/fruitless cultivars.
           Shrub forms may select
           `habit:'mossphlox'` for a low evergreen runner mat instead of a
           generic mound, or `flowerStyle:'double'` plus flowerR/flowerPetals
           for large layered blooms. Leafmounds may tune leaves/scapes/florets/
           floretR/floretGap, set scapes to zero, and add foliage spots.
           Archbells may use `archStyle:'bleedingHeart'` for heart flowers.
           Rosettes may select `flowerStyle:'daylily'` for branched scapes
           carrying open, six-tepal flowers instead of the yucca bell tower.
           Ferns stay on the one `fern` form; the carriage of the frond is
           data, not a species branch. `fronds` (count), `spread` (how wide
           the vase opens), `arch` (how far the outer fronds fall toward
           horizontal — a maidenhair's flat fan is a high arch), `reach`,
           `frondLen`/`frondVar`, and `bow`/`bowY` (rachis curvature: stiff
           shuttlecock vs lax arch) place the fronds; `pinnaN`/`pinnaLen`/
           `pinnaTip`/`pinnaW` and `pinnaFrom`/`pinnaTo` cut them, from
           hay-scented lace to holly fern's five leathery slabs.
           `taper:'both'` narrows the frond at the base as well as the tip
           (New York fern). `stipe`/`stipeW` colour the stem — maidenhair's
           near-black wire, 'Lady in Red'. `frondStyle:'strap'` is the one
           architecture switch, for undivided fronds (hart's tongue), which
           draw through drawLeaf and use pinnaW as the strap half-width.
           `fertileStyle` is 'stick' (ostrich), 'spike' (cinnamon fern's
           woolly clubs) or 'bead' (sensitive fern's persistent pods), with
           fertileN/fertileLen/fertileSpread/fertileW; it draws from sea.seed,
           so it is also what a deciduous fern shows in winter.
           Sedges stay on the `bunchgrass` form: use mound/leaves/fan/
           leafLen/leafW/spread/dome/edgeDrop to distinguish carpet,
           meadow, woodland, and wetland habits. `sedgeHabit:'palm'`
           gives Palm Sedge ranked leaves; `seedStyle` may be `mace`,
           `brush`, or `pendant` for a shared distinctive fruiting habit.
           Non-mound bunchgrasses may use `seedStyle:'fluffyRaceme'` plus
           seedTufts/seedSpan/seedAwn/seedFan for repeated hairy spikelets
           along a narrow upright fertile culm.
   sea     per-season appearance, the Oudolf heart of the game:
           fol (foliage), folTip (optional contrasting last third of a grass
           blade), bloom (flower this season, omit for none),
           seed (persistent seedhead/structure — fall/winter presence is
           the whole point), panicle (optional airy branch colour when it
           differs from the florets), eye (cone center, coneflowers only)
   photo   optional real photograph, shown in the Plant Library BELOW the four
           seasonal illustrations. It answers a different question from them —
           what does it look like in a real garden — and never replaces them,
           which is why it is optional and why most species will never have
           one. See js/photos.js for the reader, the licence allowlist and the
           validator, and docs/plant-photos.md for the human checklist that has
           to be completed before a record is written here.

           A photograph carries licence terms, and those terms are only met if
           the credit travels with the file. So this is STRUCTURED — never one
           opaque attribution string — and every field is separately readable:

             photo:{
               file:'bluestem.jpg',            // bare name under photos/
               alt:'...',                      // optional; describes the PLANT
               title:'...',                    // the file's title on Commons
               creator:'Jane Smith',           // required, always
               sourceName:'Wikimedia Commons', // or 'Own photograph'
               sourceUrl:'https://commons.wikimedia.org/wiki/File:...',
               commonsFileName:'File:...',
               license:'cc-by-sa-4.0',         // key into PHOTO_LICENSES
               isModified:true,
               modificationNote:'Resized and cropped for display',
             }

           `file` is local because the app self-hosts every asset and makes
           zero third-party requests — a privacy-policy claim, not a
           preference — while `sourceUrl` keeps the ORIGINAL file page, which
           is the only evidence the licence claim can be re-checked against.
           Those are two different facts, and collapsing them would cost
           either offline use or the provenance.
   externalLinks optional outbound references, currently { wikipedia }. A
           secondary reference at the foot of the Library card, never a
           description source: the `blurb` above is the editorial voice and
           stays the main content.

   Footprint policy:
   - Herbaceous plants occupy one plant tile; `space` drives matrix/export
     spacing and `spread` is mature-width metadata.
   - Bulbs occupy one bulb-layer tile and may share non-woody plant tiles,
     but not a woody trunk or mature shrub reservation.
   - Shrubs reserve a mature rounded footprint from
     `shrubFootprintTiles(..., true)`, using `woodyRadiusTiles(P)` from
     `spread`. Compatible clipped hedges may connect edge-to-edge.
   - Trees have one hard trunk tile. Canopy is visual/shade/soft-warning
     space, not an occupancy footprint; mature rings and shade still use
     `woodyRadiusTiles(P)`, never `cw`.

   `effectiveEstab(p)` is a display lens only: real establishment normally,
   maturity in Design mode's Established preview. Visuals may read it; placement
   legality reads true establishment (except shrubs, which reserve mature size
   by policy).

   Accuracy matters more than prettiness — Kevin grows these.
*/
